using System;using System.Linq;using UnityEditor;using UnityEngine;using LWS.TruckTeaParty;using LWS.TruckTeaParty.Editor;using LWS.TruckMechanicalBull.Editor;using LWS.TruckSports;
namespace LWS.TruckBakeOff.Editor {
 public static class BakeArt {
  public const string Folder="TruckBakeOff";
  public static ServingVessel Container(BakeMatch m,Transform parent,string name,int id,Vector3 p,ServingContents contents,Material shell,Material trim,Material filling,PhysicsMaterial contact){bool egg=contents==ServingContents.Egg;var v=ServingArt.Vessel(m,m,Folder,parent,name,id,p,!egg,shell,trim,filling,contact);v.contents=contents;
   if(contents==ServingContents.Milk){v.initialVolume=1.4f;v.capacity=1.6f;return v;}
   foreach(var c in v.physical)if(c!=null)UnityEngine.Object.DestroyImmediate(c);UnityEngine.Object.DestroyImmediate(v.shell.gameObject);var model=new GameObject(name+" original physical ingredient model").transform;model.SetParent(v.transform,false);v.shell=model;
   if(egg){ServingArt.Part(Folder,model,"Actual fragile eggshell",ServingArt.Mesh(Folder,"Smooth genuine egg profile",ImpossibleBalanceArt.Ovoid),shell,Vector3.up*.7f,new Vector3(1.1f,1.4f,1.1f));var shape=v.gameObject.AddComponent<CapsuleCollider>();shape.center=Vector3.up*.7f;shape.radius=.55f;shape.height=1.4f;shape.sharedMaterial=contact;v.physical=new Collider[]{shape};v.pourable=false;v.initialVolume=v.capacity=1;v.breakSpeed=3.4f;v.maximumHealth=.8f;UnityEngine.Object.DestroyImmediate(v.liquid.gameObject);v.liquid=null;var e=v.gameObject.AddComponent<BakeEgg>();e.match=m;e.vessel=v;return v;}
   ServingArt.Part(Folder,model,contents+" folded ingredient sack",ServingArt.Block(Folder),shell,new Vector3(0,1,0),new Vector3(1.8f,2,1.2f));for(int side=-1;side<=1;side+=2){var fold=ServingArt.Part(Folder,model,"Physically opened measuring bag fold",ServingArt.Block(Folder),shell,new Vector3(side*.45f,2.1f,.15f),new Vector3(.8f,.12f,1.3f));fold.transform.localRotation=Quaternion.Euler(0,0,side*18);}var box=v.gameObject.AddComponent<BoxCollider>();box.center=Vector3.up;box.size=new Vector3(1.8f,2,1.2f);box.sharedMaterial=contact;v.physical=new Collider[]{box};var spout=new GameObject("Actual opened powder bag pouring mouth").transform;spout.SetParent(v.transform,false);spout.localPosition=new Vector3(0,1.9f,.7f);v.spout=spout;v.pourable=true;v.capacity=contents==ServingContents.Flour?1.8f:1;v.initialVolume=v.capacity;return v;
  }
  public static ServingVessel Bowl(BakeMatch m,Transform parent,int slot,Vector3 p,Material steel,Material trim,Material batter,PhysicsMaterial contact){var v=ServingArt.Vessel(m,m,Folder,parent,"Actual weighed mixing bowl "+slot,20+slot,p,false,steel,trim,batter,contact);v.transform.localScale=new Vector3(2,.7f,2);v.body.mass=150;v.capacity=4.2f;v.initialVolume=0;v.contents=ServingContents.Milk;v.maximumHealth=8;v.breakSpeed=6;var spout=new GameObject("Actual mixing bowl pouring lip").transform;spout.SetParent(v.transform,false);spout.localPosition=new Vector3(0,1.5f,1);v.spout=spout;return v;}
  public static ServingVessel Nozzle(BakeMatch m,ServingArm arm,int slot,Material metal,Material cream,PhysicsMaterial contact){var v=ServingArt.Vessel(m,m,Folder,arm.gear,"Gimballed actual cream reservoir and nozzle "+slot,28+slot,arm.grip.position,false,metal,metal,cream,contact);foreach(var c in v.physical)if(c!=null)UnityEngine.Object.DestroyImmediate(c);UnityEngine.Object.DestroyImmediate(v.shell.gameObject);UnityEngine.Object.DestroyImmediate(v.liquid.gameObject);v.liquid=null;v.physical=Array.Empty<Collider>();var model=new GameObject("Working stabilized decorating nozzle").transform;model.SetParent(v.transform,false);v.shell=model;ServingArt.Part(Folder,model,"Cream pressure reservoir",ServingArt.Mesh(Folder,"Small pressure frosting reservoir",()=>ImpossibleBalanceArt.Lathe(new[]{new Vector2(0,0),new Vector2(.3f,0),new Vector2(.35f,.2f),new Vector2(.35f,1),new Vector2(.2f,1.2f),new Vector2(0,1.3f)},24)),metal,Vector3.zero,Vector3.one);ServingArt.Part(Folder,model,"Fluted decorating nozzle tip",ServingArt.Mesh(Folder,"Fluted conical cream nozzle",()=>ImpossibleBalanceArt.Lathe(new[]{new Vector2(.2f,0),new Vector2(.12f,-.3f),new Vector2(.05f,-.4f)},20)),metal,Vector3.zero,Vector3.one);var spout=new GameObject("Actual downward cream outlet").transform;spout.SetParent(v.transform,false);spout.localPosition=Vector3.down*.42f;spout.localRotation=Quaternion.Euler(90,0,0);v.spout=spout;v.contents=ServingContents.Cream;v.initialVolume=v.capacity=3.2f;v.pourable=false;v.maximumHealth=10000;v.breakSpeed=1000;v.body.isKinematic=true;v.body.useGravity=false;return v;}
 }
}
